#!/usr/bin/env node
/**
 * Builds the browser extension's generated files from the site's data:
 *   extension/calculator.js  copy of the calculator engine (name matching)
 *   extension/data.js        compact nutrition data for every live brand
 * Run after changing any dataset:  node scripts/build-extension.js
 * (tests fail if these files are out of date).
 */
'use strict';
const fs = require('fs');
const path = require('path');

const ROOT = path.join(__dirname, '..');
const DATA = path.join(ROOT, 'theme', 'assets', 'data');
const SITE = 'https://fastfoodnutritioncalc.com';

// Brand page paths, mirrored from theme/inc/brands-registry.php.
function brandUrls() {
	const php = fs.readFileSync(path.join(ROOT, 'theme', 'inc', 'brands-registry.php'), 'utf8');
	const out = {};
	const re = /'slug'\s*=>\s*'([a-z0-9-]+)'[\s\S]*?'url'\s*=>\s*'([^']+)'/g;
	let m;
	while ((m = re.exec(php))) { out[m[1]] = SITE + m[2]; }
	return out;
}

// Names a delivery app may use for the restaurant (page title / heading).
const ALIASES = {
	'mcdonalds': ["mcdonald's", 'mcdonalds'], 'kfc': ['kfc', 'kentucky fried chicken'], 'subway': ['subway'],
	'dunkin': ["dunkin'", 'dunkin', 'dunkin donuts'], 'chipotle': ['chipotle'], 'taco-bell': ['taco bell'],
	'wendys': ["wendy's", 'wendys'], 'burger-king': ['burger king'], 'dominos': ["domino's", 'dominos'],
	'pizza-hut': ['pizza hut'], 'chick-fil-a': ['chick-fil-a', 'chick fil a', 'chickfila'], 'panera-bread': ['panera'],
	'five-guys': ['five guys'], 'panda-express': ['panda express'], 'dairy-queen': ['dairy queen', 'dq grill']
};

function buildData() {
	const urls = brandUrls();
	const brands = [];
	for (const f of fs.readdirSync(DATA).filter(f => f.endsWith('.json')).sort()) {
		const d = JSON.parse(fs.readFileSync(path.join(DATA, f), 'utf8'));
		const slug = f.replace('.json', '');
		if (slug === 'chipotle') { continue; } // sold by ingredient, nothing to match on a menu
		brands.push({
			slug, name: d.brand, url: urls[slug] || SITE, aliases: ALIASES[slug] || [d.brand.toLowerCase()],
			categories: d.categories.map(c => ({ id: c.id, name: c.name, items: c.items.map(i => ({
				id: i.id, name: i.name, calories: i.calories, protein: i.protein, carbs: i.carbs, fat: i.fat, sodium: i.sodium
			})) }))
		});
	}
	return '/* Generated by scripts/build-extension.js. Do not edit. */\nvar FFNC_EXT_DATA = ' + JSON.stringify({ site: SITE, brands }) + ';\n';
}

function buildEngine() {
	return '/* Copied from theme/assets/js/calculator.js by scripts/build-extension.js. Do not edit. */\n' +
		fs.readFileSync(path.join(ROOT, 'theme', 'assets', 'js', 'calculator.js'), 'utf8');
}

const FILES = {
	[path.join(ROOT, 'extension', 'data.js')]: buildData,
	[path.join(ROOT, 'extension', 'calculator.js')]: buildEngine,
};

if (require.main === module) {
	for (const [file, fn] of Object.entries(FILES)) {
		fs.writeFileSync(file, fn());
		console.log('wrote ' + path.relative(process.cwd(), file));
	}
}
module.exports = { FILES };
